def transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if (r,c) in seen or grid[r][c]==bg: continue
        color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          x,y=q.pop(); comp.append((x,y))
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=x+dx,y+dy
            if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
              seen.add((a,b)); q.append((a,b))
        comps.append((color,comp))
    out=[row[:] for row in grid]
    for color,comp in comps:
      if len(comp)!=1: continue
      r,c=comp[0]; candidates=[]
      for other,region in comps:
        if other==color or len(region)<4: continue
        rs=[p[0] for p in region]; cs=[p[1] for p in region]
        r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
        area=(r1-r0+1)*(c1-c0+1)
        if r0<=r<=r1 and c0<=c<=c1:
          coverage=len(region)/area
          if coverage>=0.7: candidates.append((coverage,other))
      if candidates:
        out[r][c]=max(candidates)[1]
      else:
        neighbors=[grid[a][b] for dx in (-1,0,1) for dy in (-1,0,1) if (dx or dy) and 0<=(a:=r+dx)<h and 0<=(b:=c+dy)<w]
        counts=Counter(neighbors); best=max(counts.values()); winners=[v for v,n in counts.items() if n==best]
        out[r][c]=winners[0] if len(winners)==1 else bg
    return out
